// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {SimpleWallet} from "../src/SimpleWallet.sol";

contract InvMutTest is Test {
    SimpleWallet c;
    function setUp() public { c = new SimpleWallet(); }

    function testFuzz_property(uint256 amount, address) public {
        amount = bound(amount, 1, address(this).balance == 0 ? 1 ether : 1 ether);

        Reverter bad = new Reverter();

        vm.deal(address(c), amount);

        bool ok;
        try c.sendMoney(address(bad), amount) {
            ok = true;
        } catch {
            ok = false;
        }

        assertTrue(!ok);
    }
}

contract Reverter {
    fallback() external payable {
        revert("fail");
    }
}
